export const importCatalogItems = async (
  importCatalogItemsBody: ImportCatalogItemsBody,
  options?: Parameters<typeof customFetch>[1],
): Promise<ImportResult> => {
  const formData = new FormData()
  formData.append(
    `file`,
    importCatalogItemsBody.file instanceof Blob
      ? importCatalogItemsBody.file
      : new Blob([importCatalogItemsBody.file], { type: 'text/csv' }),
  )
  if (importCatalogItemsBody.dryRun !== undefined) {
    formData.append(`dryRun`, importCatalogItemsBody.dryRun.toString())
  }

  return customFetch<ImportResult>(getImportCatalogItemsUrl(), {
    ...options,
    method: 'POST',
    body: formData,
  })
}

